package chatui

const RenderingStyles = `.chatrender-personal summary{min-height:44px;display:flex;align-items:center;overflow-wrap:anywhere}.chatrender-personal summary:focus-visible{outline:2px solid var(--hcm-color-focus);outline-offset:2px}.chatrender-settings,.chatrender-view,.chatrender-indicator{min-width:0;max-width:100%;color:var(--hcm-color-text);background:var(--hcm-color-surface);border-radius:var(--hcm-radius-control);padding:12px;box-sizing:border-box;overflow-wrap:anywhere}.chatrender-settings{display:grid;gap:12px}.chatrender-settings select,.chatrender-settings button,.chatrender-mark button,.chatrender-check{min-height:44px;max-width:100%}.chatrender-settings select{width:100%;min-width:0;color:var(--hcm-color-text);background:var(--hcm-color-surface);border:1px solid var(--hcm-color-border);border-radius:var(--hcm-radius-control)}.chatrender-languages{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,120px),1fr));min-width:0;border:1px solid var(--hcm-color-border)}.chatrender-check{display:flex;align-items:center;gap:8px;overflow-wrap:anywhere}.chatrender-check input{flex:none;width:24px;height:24px;accent-color:var(--hcm-color-brand-primary)}.chatrender-mark,.chatrender-indicator{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.chatrender-indicator h3{flex-basis:100%;margin:0}.chatrender-text{white-space:pre-wrap;overflow-wrap:anywhere}.chatrender-mark{font-size:.875rem;color:var(--hcm-color-text-muted)}.chatrender-settings :focus-visible,.chatrender-mark :focus-visible{outline:2px solid var(--hcm-color-brand-primary);outline-offset:2px}.chatrender-language-count{border:1px solid var(--hcm-color-border);border-radius:var(--hcm-radius-control);padding:6px}@media(prefers-reduced-motion:reduce){.chatrender-settings *,.chatrender-mark *{animation:none;transition:none}}`
